mkdir -p /tmp/sv-95abfb2174654e0db7fcfbcefb6ca732/typed-meta && cd /tmp/sv-95abfb2174654e0db7fcfbcefb6ca732/typed-meta && dotnet new console --framework net11.0 -o . --force -n TypedMeta >/dev/null 2>&1 && cat > Program.cs << 'EOF'
using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed metadata retrieval: GetTypeInfo<T>()
//    Returns JsonTypeInfo<T> directly — no cast needed.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Kind          : {personInfo.Kind}");
Console.WriteLine($"  Properties    : {personInfo.Properties.Count}");

// Prove it works end-to-end by round-tripping with the typed info
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
var p = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"  Round-tripped : {p}");

Console.WriteLine();

// 2) Probe without throwing: TryGetTypeInfo(Type, out JsonTypeInfo?)
//    Returns false instead of throwing if the type isn't resolvable.
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
{
    Console.WriteLine($"TryGetTypeInfo(Person) succeeded → {info!.Type.Name}");
}

// Now try a type the resolver *cannot* handle (a custom context that
// only knows about Person, not about UnknownRecord).
var limitedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new LimitedContext()
};

if (limitedOptions.TryGetTypeInfo(typeof(UnknownRecord), out JsonTypeInfo? missing))
{
    Console.WriteLine("Should not reach here");
}
else
{
    Console.WriteLine($"TryGetTypeInfo(UnknownRecord) returned false — no throw!");
}

// --- Types ---

public record Person(string Name, int Age);
public record UnknownRecord(string X);

// A source-gen context that only resolves Person
[JsonSerializable(typeof(Person))]
public partial class LimitedContext : JsonSerializerContext;
EOF
dotnet run

